Only ``jax.scipy.linalg.solve`` is referenced (inside
``model.make_kernelized_rr_forward``, which the SVD-AE path never calls).
"""

import numpy as np


class _Linalg:
    @staticmethod
    def solve(a, b, sym_pos=False, **kwargs):
        return np.linalg.solve(np.asarray(a), np.asarray(b))


linalg = _Linalg()

"""Minimal stand-in for ``neural_tangents.stax`` (see compat/jax/__init__.py).

``repo/model.py`` builds an infinite-width NTK feature map with
``stax.serial(stax.Flatten(), stax.Dense(1024), stax.Relu(), ...)``.  That
feature map is only consumed by ``make_kernelized_rr_forward``, i.e. by the
``inf-ae`` baseline.  For ``--model svd-ae`` the returned ``kernel_fn`` is
never invoked, so a lightweight layer-description object is enough to let the
author's modules import and run unchanged.
"""


class Layer:
    def __init__(self, name, **kwargs):
        self.name = name
        self.kwargs = kwargs

    def __repr__(self):
        return "stax.{}({})".format(
            self.name, ", ".join("{}={}".format(k, v) for k, v in self.kwargs.items())
        )


class Flatten(Layer):
    def __init__(self):
        super().__init__("Flatten")


class Dense(Layer):
    def __init__(self, out_dim=1, W_std=1.0, b_std=1.0, parameterization="ntk"):
        super().__init__(
            "Dense", out_dim=out_dim, W_std=W_std, b_std=b_std,
            parameterization=parameterization,
        )


class Relu(Layer):
    def __init__(self):
        super().__init__("Relu")


def serial(*layers):
    """Return the (init_fn, apply_fn, kernel_fn) triple, as real stax does."""

    def init_fn(rng, input_shape):
        return input_shape, ()

    def apply_fn(params, inputs, **kwargs):
        raise NotImplementedError(
            "compat neural_tangents stub: the NTK apply_fn is only used by the "
            "inf-ae baseline, not by SVD-AE."
        )

    def kernel_fn(*args, **kwargs):
        raise NotImplementedError(
            "compat neural_tangents stub: the NTK kernel_fn is only used by the "
            "inf-ae baseline, not by SVD-AE."
        )

    return init_fn, apply_fn, kernel_fn

